@startuml

class OilCompany {}

class GasStation {}

class Pump {
  + Type : string
  + CurrentLevel : double
  + ReorderingLevel : double
  + CriticalLevel : double
  + Blocked : boolean
}

class Reservoir {
  + Quantity : double
}

class RefuelTurn {
  + Amount : double
}

class Customer {
  + Name : string
  + Suspended : boolean
}

class FuelCard {
  + Blocked : boolean
}

class Invoice {
  + Month : string
  + Discount : double
}

class Payment {
  + Amount : double
}

GasStation "1" -- "*" Pump
Pump "1" *-- "1" Reservoir
Pump "1" -- "0..*" RefuelTurn
Customer "1" -- "0..*" RefuelTurn
Customer "1" -- "0..1" FuelCard
Customer "1" -- "0..*" Invoice
Invoice "1" -- "0..*" RefuelTurn
Invoice "1" -- "0..*" Payment

@enduml

